// Public page layouts share the studio's live photographs, events and settings.
const collectionCards=[['Weddings','The beginning of forever.',0],['Pre-Wedding','A story only you can tell.',1],['Maternity','A little miracle. A new chapter.',2],['Portraits','Beautifully, unmistakably you.',3]];
const studioPhoto=(category,fallback=0)=>photos.find(p=>p.category===category&&p.featured)||photos.find(p=>p.category===category)||samples[fallback];
const sampleNote=()=>'';
const smallCamera='<svg viewBox="0 0 64 48" width="50" height="40" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 12h16l5-8h16l5 8h16v32H3Z"/><circle cx="32" cy="27" r="11"/></svg>';
function footerMarkup(){return `<div class="footer-top"><div class="footer-identity"><a href="/" aria-label="Imagica Portraits home"><img src="/assets/imagica-wordmark.svg" alt="Imagica Portraits" width="250" height="81"></a><p>We Bring Imagination Into Reality.</p><p>Thoughtful photographs.<br>Beautiful stories. A lifetime of feeling.</p></div><div><span class="footer-label">Explore</span><a href="/">Home</a><a href="/about/">Our story</a><a href="/gallery/">The collections</a><a href="/events/">Events & sessions</a><a href="/contact/">Get in touch</a></div><div><span class="footer-label">The collections</span>${['Weddings','Pre-Wedding','Birthdays','Portraits','Maternity','Fashion & Creative'].map(c=>`<a href="/gallery/?category=${encodeURIComponent(c)}">${c}</a>`).join('')}</div><div class="footer-contact"><span class="footer-label">Let’s make memories</span><h3>Your story<br>starts here.</h3>${settings.phone?`<a href="${booking()}" target="_blank" rel="noopener">WhatsApp: +${esc(settings.phone)} ↗</a>`:'<a href="/contact/">Plan your next shoot ↗</a>'}${settings.email?`<a href="mailto:${esc(settings.email)}">${esc(settings.email)}</a>`:''}${settings.instagram?`<a href="${esc(safeUrl(settings.instagram))}" target="_blank" rel="noopener">Follow on Instagram ↗</a>`:''}${settings.location?`<p>${esc(settings.location)}</p>`:''}</div></div><div class="footer-bottom"><span>© <span id="year">${new Date().getFullYear()}</span> Imagica Portraits. All rights reserved.</span><span>Made for the moments that matter.</span><a href="/admin/">Studio admin ↗</a></div>`}
function renderFooter(){const footer=$('#site-footer');if(footer)footer.innerHTML=footerMarkup()}
function home(){const slides=[{category:'Weddings',tag:'For your once-in-a-lifetime',title:'Some moments<br>deserve <em>forever.</em>',text:'Turning your moments into timeless memories. A thoughtful eye, a little imagination, and a story that is entirely yours.',photo:studioPhoto('Weddings',4)},{category:'Pre-Wedding',tag:'A little adventure. A lot of love.',title:'Before the vows,<br><em>there was you.</em>',text:'Slow down, find your favourite place, and let your story unfold. Pre-wedding photographs with room to be yourselves.',photo:studioPhoto('Pre-Wedding',0)},{category:'Maternity',tag:'For the love that keeps growing',title:'Keep the joy.<br><em>Keep the feeling.</em>',text:'The quiet anticipation. The growing love. Beautiful maternity photographs to remember the beginning of your next chapter.',photo:studioPhoto('Maternity',2)}];const selected=photos.filter(p=>p.featured),frames=(selected.length?selected:photos).slice(0,4);const upcoming=events.filter(e=>new Date(e.date)>=new Date()).slice(0,3);return `<div class="home-page redesigned"><div class="hero-kicker"><span>Imagica Portraits</span><span>Love. Life. Everything in between.</span></div><div class="home-banner" aria-label="Photography highlights" aria-roledescription="carousel">${slides.map((s,i)=>`<article class="banner-frame" data-banner-frame="${i}" ${i?'hidden':''} aria-label="${i+1} of 3: ${s.category}"><img class="banner-backdrop" src="${esc(s.photo.url)}" alt="" aria-hidden="true"><img class="banner-image" src="${esc(s.photo.url)}" alt="${esc(s.photo.title)}" ${i?'loading="lazy"':'fetchpriority="high"'}><div class="banner-shade"></div><div class="banner-copy"><span class="eyebrow">${s.tag}</span>${i?'<h2>':'<h1>'}${s.title}${i?'</h2>':'</h1>'}<p>${s.text}</p><div class="banner-actions"><a class="button" href="/gallery/?category=${encodeURIComponent(s.category)}">Explore ${s.category} ↗</a><a class="button outline" href="/contact/">Book a shoot ↗</a></div></div></article>`).join('')}<div class="banner-bottom"><span>WE BRING IMAGINATION INTO REALITY.</span><div class="banner-controls"><button data-banner-pause aria-label="Pause slideshow" aria-pressed="false">Ⅱ</button><button data-banner-step="-1" aria-label="Previous banner">←</button><div class="banner-dots">${slides.map((s,i)=>`<button data-banner-to="${i}" aria-label="Show ${s.category} banner" aria-pressed="${!i}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><button data-banner-step="1" aria-label="Next banner">→</button></div></div></div><section class="intro-editorial"><span class="eyebrow">Every Frame Tells a Story.</span><h2>The art of <em>remembering.</em></h2><p>Some photographs show you a moment.<br>The ones we love bring you right back to it.</p><a class="text-link" href="/about/">Discover Imagica Portraits ↗</a></section><section class="home-collections"><div class="section-title"><div><span class="eyebrow">Your life, in beautiful chapters</span><h2>What are we <em>celebrating?</em></h2></div><a class="text-link" href="/gallery/">All collections ↗</a></div><div class="home-category-grid">${collectionCards.map(([category,copy,index])=>{const p=studioPhoto(category,index);return `<a class="home-category" href="/gallery/?category=${encodeURIComponent(category)}"><div class="home-category-image"><img src="${esc(p.url)}" alt="${esc(p.title)}" loading="lazy"><span class="category-arrow">↗</span></div><div class="category-caption"><span class="eyebrow">0${index+1}</span><div><h3>${category}</h3><p>${copy}</p></div></div></a>`}).join('')}</div>${collectionCards.some(([c,,i])=>studioPhoto(c,i).id.startsWith('sample'))?sampleNote():''}</section><section class="home-story cream"><div class="home-story-images"><img class="story-main" src="/assets/msr-6500.jpg" alt="An intimate moment at a wedding celebration" loading="lazy"><img class="story-detail" src="/assets/msr-4699.jpg" alt="Wedding rings photographed by Imagica Portraits" loading="lazy"><span class="story-signature script">Made of moments.</span></div><div class="home-story-copy"><span class="eyebrow">The heart behind the lens</span><h2>A beautiful frame.<br><em>A feeling, forever.</em></h2><p>The laughter you couldn’t hold back. The glance only you noticed. The people who make a place feel like home.</p><p>We bring a thoughtful approach and an artistic eye to the things that matter to you. With space to feel comfortable, be yourself, and enjoy the moment.</p><a class="text-link" href="/about/">Our story & approach ↗</a></div></section><section class="home-selected"><div class="section-title"><div><span class="eyebrow">From the collection</span><h2>Little moments.<br><em>Lasting memories.</em></h2></div><a class="text-link" href="/gallery/">Explore our work ↗</a></div><div class="home-selected-grid">${frames.map(p=>`<button class="photo home-selected-photo" data-photo="${esc(p.id)}" aria-label="View ${esc(p.title)}"><img src="${esc(p.url)}" alt="${esc(p.description||p.title)}" loading="lazy"><span>${esc(p.title)}<small>${esc(p.category)}</small></span></button>`).join('')}</div>${photos.some(p=>p.id.startsWith('sample'))?sampleNote():''}</section><section class="home-process cream"><div><span class="eyebrow">A lovely experience, from the start</span><h2>Your story.<br><em>Our attention.</em></h2><p>A little planning. A relaxed session.<br>Something beautiful to keep.</p><a class="text-link" href="/contact/">Start your story ↗</a></div><div class="process-steps">${[['Tell us your idea.','Share the occasion, your preferred date, and the feeling you have in mind.'],['Make yourself at home.','We’ll plan the details together and guide you through a comfortable session.'],['Come back to the feeling.','Keep the photographs that bring this chapter of your life back into focus.']].map(([title,copy],i)=>`<article><span>0${i+1}</span><div><h3>${title}</h3><p>${copy}</p></div></article>`).join('')}</div></section>${upcoming.length?`<section><div class="section-title"><div><span class="eyebrow">On the calendar</span><h2>More moments <em>ahead.</em></h2></div><a class="text-link" href="/events/">All events ↗</a></div>${eventCards(upcoming)}</section>`:''}${settings.testimonial?`<section class="quote-block"><span class="eyebrow">A client’s story</span><blockquote>“${esc(settings.testimonial)}”</blockquote><p>${esc(settings.testimonialName)}</p></section>`:''}${cta()}</div>`}
function about(){return `<div class="story-page"><section class="about-opening"><div><span class="eyebrow">Meet Imagica Portraits</span><h1>For the stories<br>that <em>stay with you.</em></h1><p class="lede">We Bring Imagination Into Reality.</p><p>We believe photographs should feel as personal as the moments they hold. Honest expression. Beautiful light. A connection you can feel.</p><a class="text-link" href="/contact/">Let’s tell your story ↗</a></div><figure><img src="/assets/msr-4059.jpg" alt="A studio portrait by Imagica Portraits" fetchpriority="high"><figcaption>Considered details. A personal perspective.</figcaption></figure></section><section class="about-manifesto cream"><span class="eyebrow">A note from the studio</span><h2>It starts with a connection.<br>It stays as <em>a feeling.</em></h2><div class="manifesto-body"><p>Your photographs are part of your story. We start by listening: to your ideas, the people involved, and the moments you’re looking forward to.</p><p>From weddings and celebrations to a portrait just for you, our approach is calm, collaborative, and shaped around what makes this chapter yours.</p></div></section><section class="about-principles"><div class="section-title"><div><span class="eyebrow">The way we see it</span><h2>People at the heart.<br><em>Care in every frame.</em></h2></div></div><div class="principle-grid">${[['Connection','You should feel comfortable in front of the lens. We make space for your personality and the way you naturally connect.'],['Imagination','A creative perspective, considered composition, and attention to the details that make a photograph feel special.'],['Intention','We photograph the moments that mean something to you, with a thoughtful process from your first hello.']].map(([title,copy],i)=>`<article><span class="eyebrow">0${i+1}</span><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div></section><section class="about-studio cream"><img src="/assets/msr-7872.jpg" alt="A maternity story by Imagica Portraits" loading="lazy"><div><span class="eyebrow">Behind the lens</span><h2>${settings.photographerName?esc(settings.photographerName):'Your story, with<br><em>a little imagination.</em>'}</h2><p class="studio-biography">${esc(settings.studioBio||'Every shoot starts with a conversation. We take time to understand your plans, the people involved, and the moments you want to remember.')}</p><p>Let’s talk about your occasion, find the right atmosphere, and make photographs that feel like you.</p><a class="button" href="/contact/">Meet us through your story ↗</a></div></section>${cta()}</div>`}
function gallery(){return `<div class="collection-page"><div class="page-head"><span class="eyebrow">The Imagica collections</span><h1>Life moves. <em>Memories stay.</em></h1><p>Love, laughter, and little things. Explore the stories through our lens.</p></div><section class="gallery-section"><div class="gallery-toolbar"><span>Find your chapter</span><div class="filters">${['All',...cats].map(c=>`<button class="filter ${filter===c?'active':''}" data-filter="${esc(c)}">${c}</button>`).join('')}</div></div><div class="gallery" id="gallery-grid"></div>${photos.some(p=>p.id.startsWith('sample'))?sampleNote():''}</section>${cta()}</div>`}
let eventFilter='All';
function eventCards(list){if(!list.length)return `<div class="empty editorial-empty">${smallCamera}<h3>A new chapter is on its way.</h3><p>There are no events in this collection yet.<br>Ask us about a date or a session of your own.</p><a class="text-link" href="/contact/">Plan a session ↗</a></div>`;return `<div class="events-grid">${list.map(e=>{const date=new Date(e.date),past=date<new Date();return `<article class="event"><div class="event-visual">${e.cover_url?`<img src="${esc(safeUrl(e.cover_url))}" alt="${esc(e.title)}" loading="lazy">`:`<div class="event-cover-placeholder">${smallCamera}<span>Imagica Portraits</span></div>`}<span class="event-status">${past?'Completed':'Upcoming'}</span><div class="event-date"><strong>${date.toLocaleDateString('en-IN',{day:'2-digit',timeZone:'Asia/Kolkata'})}</strong><span>${date.toLocaleDateString('en-IN',{month:'short',timeZone:'Asia/Kolkata'})}</span></div></div><div class="event-body"><span class="eyebrow">${date.toLocaleDateString('en-IN',{year:'numeric',timeZone:'Asia/Kolkata'})} · ${date.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'})} IST</span><h3>${esc(e.title)}</h3><p class="event-location">⌖ ${esc(e.location)}</p><p>${esc(e.description)}</p>${e.images?.length?`<details><summary>View event photographs (${e.images.length})</summary><div class="event-thumbnails">${e.images.map(u=>`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener"><img src="${esc(safeUrl(u))}" alt="${esc(e.title)} event photograph" loading="lazy"></a>`).join('')}</div></details>`:''}<a class="text-link" href="${booking()}">Ask about this event ↗</a></div></article>`}).join('')}</div>`}
function filteredEvents(){return events.filter(e=>eventFilter==='All'||(eventFilter==='Upcoming'?new Date(e.date)>=new Date():new Date(e.date)<new Date()))}
function eventsPage(){return `<div class="events-page"><div class="page-head"><span class="eyebrow">Gather. Celebrate. Remember.</span><h1>Make room for<br><em>something lovely.</em></h1><p>Upcoming sessions, special occasions, and celebrations from the studio.</p></div><section class="events-section"><div class="events-toolbar"><h2>The studio <em>calendar.</em></h2><div class="filters">${['All','Upcoming','Completed'].map(c=>`<button class="filter ${c===eventFilter?'active':''}" data-event-filter="${c}">${c}</button>`).join('')}</div></div><div id="event-results">${eventCards(filteredEvents())}</div></section><section class="events-invitation cream"><span class="script">An idea of your own?</span><h2>Every occasion deserves<br><em>a beautiful memory.</em></h2><p>Tell us what you’re planning. We’ll help bring it into focus.</p><a class="button" href="/contact/">Talk about your event ↗</a></section></div>`}
function bindEventFilters(){document.querySelectorAll('[data-event-filter]').forEach(b=>b.onclick=()=>{eventFilter=b.dataset.eventFilter;$('#event-results').innerHTML=eventCards(filteredEvents());document.querySelectorAll('[data-event-filter]').forEach(x=>x.classList.toggle('active',x.dataset.eventFilter===eventFilter))})}
function contact(){return `<div class="contact-page"><div class="page-head"><span class="eyebrow">A hello can start something beautiful.</span><h1>Tell us<br><em>your story.</em></h1><p>The date. The place. The people. The little idea you can’t stop thinking about.</p></div><section class="contact-workspace"><aside class="contact-card"><span class="eyebrow">Imagica Portraits</span><h2>Let’s make<br><em>memories.</em></h2><p>For weddings, portraits, birthdays, and celebrations of every kind.</p><div class="contact-card-details">${settings.phone?`<div><small>WhatsApp & booking</small><a href="${booking()}" target="_blank" rel="noopener">+${esc(settings.phone)} ↗</a></div>`:''}${settings.email?`<div><small>Email the studio</small><a href="mailto:${esc(settings.email)}">${esc(settings.email)} ↗</a></div>`:''}${settings.instagram?`<div><small>Follow the stories</small><a href="${esc(safeUrl(settings.instagram))}" target="_blank" rel="noopener">Instagram ↗</a></div>`:''}${settings.location?`<div><small>Find us</small><p>${esc(settings.location)}</p></div>`:''}${!settings.phone&&!settings.email?'<div><small>Contact details</small><p>The studio’s booking details are being updated. Please check back soon.</p></div>':''}</div><span class="script">With imagination, always.</span></aside><form id="inquiry" class="inquiry-card"><span class="eyebrow">Start planning your shoot</span><h2>A few details.<br><em>A world of possibilities.</em></h2><div class="form-grid"><label>Your name<input name="name" required maxlength="100" autocomplete="name" placeholder="What should we call you?"></label><label>Phone number<input name="phone" required type="tel" maxlength="25" autocomplete="tel" placeholder="Your contact number"></label><label>The occasion<select name="type">${options()}</select></label><label>Your preferred date<input name="date" type="date" min="${new Date(Date.now()+19800000).toISOString().slice(0,10)}" required></label><label class="wide">Tell us what you have in mind<textarea name="message" required maxlength="2000" placeholder="The venue, your ideas, and the feeling you’d love to capture…"></textarea></label></div><button class="button" type="submit">Prepare WhatsApp inquiry ↗</button><p class="form-note">Your message opens in WhatsApp for you to review and send.${settings.phone?'':' WhatsApp booking will be available when the studio adds its number.'}</p></form></section><section class="contact-faq"><span class="eyebrow">A little help before hello</span><h2>Good things <em>to know.</em></h2>${[['What details should I share?','Start with your occasion, preferred date, location, and any ideas you have. We can plan the finer details together.'],['Can I book a shoot for a different occasion?','Of course. Tell us about your plans in the message field, whether it is a family gathering, a creative idea, or a milestone of your own.'],['Does the form send my message automatically?','You stay in control. The form prepares your message and opens WhatsApp, where you can review it before sending.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section></div>`}
